int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct airspy_device *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    mutex_init(&dev->lock);
    mutex_init(&dev->ctrl_mutex);

    ret = usb_fill_control_urb(dev->ctrl_urb, dev->udev,
                               USB_DIR_IN | USB_TYPE_VENDOR | USB_RECIP_DEVICE,
                               AIRSPY_USB_CTRL_REQUEST,
                               dev->ctrl_buffer, AIRSPY_USB_CTRL_SIZE,
                               airspy_ctrl_callback, dev);
    if (ret < 0)
        goto error_free_dev;

    ret = airspy_init_vb2_queue(dev);
    if (ret < 0)
        goto error_free_dev;

    ret = airspy_register_v4l2_device(dev);
    if (ret < 0)
        goto error_cleanup_vb2;

    ret = airspy_init_ctrl_handlers(dev);
    if (ret < 0)
        goto error_unregister_v4l2;

    dev_info(&dev->udev->dev, "Airspy device registered with board ID 0x%x and firmware version %d.%d\n",
             dev->board_id, dev->firmware_version >> 8, dev->firmware_version & 0xff);

    return 0;

error_unregister_v4l2:
    airspy_unregister_v4l2_device(dev);
error_cleanup_vb2:
    airspy_cleanup_vb2_queue(dev);
error_free_dev:
    kfree(dev);
    return ret;
}

int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct airspy_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->udev = usb_get_dev(usb_ifnum_to_dev(intf));
    dev->intf = intf;

    mutex_init(&dev->lock);
    INIT_LIST_HEAD(&dev->buf_list);

    ret = airspy_usb_init_ctrl_msg(dev);
    if (ret < 0)
        goto err_free_dev;

    ret = airspy_usb_get_board_id(dev);
    if (ret < 0)
        goto err_free_dev;

    ret = airspy_usb_get_version(dev);
    if (ret < 0)
        goto err_free_dev;

    ret = videobuf2_queue_alloc(&dev->vb_queue, &airspy_vb_queue_ops,
                                &dev->lock, V4L2_BUF_TYPE_VIDEO_CAPTURE,
                                V4L2_MEMORY_MMAP, NULL, NULL, dev);
    if (ret < 0)
        goto err_free_dev;

    ret = airspy_v4l2_register_video(dev);
    if (ret < 0)
        goto err_free_vb_queue;

    dev->vdev.ctrl_handler = dev->ctrl_handler;
    ret = v4l2_device_register_subdev(&dev->v4l2_dev, &dev->subdev);
    if (ret < 0)
        goto err_unregister_video;

    dev_info(&dev->intf->dev, "Airspy board ID %d, firmware version %d.%d\n",
             dev->board_id, dev->fw_version >> 8, dev->fw_version & 0xff);

    return 0;

err_unregister_video:
    video_unregister_device(&dev->vdev);
err_free_vb_queue:
    videobuf2_queue_free(&dev->vb_queue);
err_free_dev:
    kfree(dev);
    return ret;
}

int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct airspy_dev *sdev;
    int ret;

    sdev = kzalloc(sizeof(*sdev), GFP_KERNEL);
    if (!sdev)
        return -ENOMEM;

    mutex_init(&sdev->lock);
    mutex_init(&sdev->v4l2_mutex);

    sdev->udev = usb_get_dev(usb_ifnum_to_index(intf, 0));
    sdev->interface = usb_get_intf(intf);

    ret = usb_set_interface(sdev->udev, 0, 0);
    if (ret < 0)
        goto error;

    ret = airspy_usb_init_ctrl_msg(sdev);
    if (ret < 0)
        goto error;

    ret = airspy_usb_get_board_id(sdev);
    if (ret < 0)
        goto error;

    ret = airspy_usb_get_firmware_version(sdev);
    if (ret < 0)
        goto error;

    ret = airspy_video_register(sdev);
    if (ret < 0)
        goto error;

    ret = airspy_usb_setup_controls(sdev);
    if (ret < 0)
        goto error;

    usb_set_intfdata(intf, sdev);

    dev_info(&sdev->udev->dev, "Airspy board ID 0x%x, firmware version %d.%d.%d",
             sdev->board_id, sdev->fw_version[0], sdev->fw_version[1], sdev->fw_version[2]);

    return 0;

error:
    airspy_usb_cleanup(sdev);
    return ret;
}

int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct airspy_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->udev = usb_get_dev(usb_ifnum_to_index(intf));
    dev->intf = usb_get_intf(intf);

    mutex_init(&dev->lock);
    INIT_LIST_HEAD(&dev->buf_list);
    spin_lock_init(&dev->slock);

    ret = airspy_usb_init_vb2_queue(dev);
    if (ret < 0)
        goto err_free_dev;

    ret = airspy_usb_init_v4l2(dev);
    if (ret < 0)
        goto err_cleanup_vb2;

    ret = airspy_usb_init_controls(dev);
    if (ret < 0)
        goto err_cleanup_v4l2;

    ret = airspy_usb_send_board_id(dev);
    if (ret < 0)
        goto err_cleanup_controls;

    ret = airspy_usb_send_firmware_version(dev);
    if (ret < 0)
        goto err_cleanup_controls;

    usb_set_intfdata(intf, dev);

    dev_info(&dev->intf->dev,
             "Airspy device registered (id: %d, firmware version: %d.%d.%d)\n",
             dev->board_id, dev->fw_version[0], dev->fw_version[1], dev->fw_version[2]);

    return 0;

err_cleanup_controls:
    airspy_usb_cleanup_controls(dev);
err_cleanup_v4l2:
    airspy_usb_cleanup_v4l2(dev);
err_cleanup_vb2:
    airspy_usb_cleanup_vb2_queue(dev);
err_free_dev:
    kfree(dev);
    return ret;
}

#include <linux/usb.h>
#include <linux/videodev2.h>
#include <linux/mutex.h>
#include <linux/slab.h>
#include <linux/v4l2-dev.h>

#include <media/v4l2-ctrls.h>
#include <media/v4l2-device.h>
#include <media/v4l2-ioctl.h>
#include <media/v4l2-fh.h>

#include "airspy.h"

int airspy_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct airspy_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->udev = usb_get_dev(usb_ifnum_to_index(intf, 0));
    dev->intf = intf;
    usb_set_intfdata(intf, dev);

    mutex_init(&dev->lock);
    init_waitqueue_head(&dev->wait);

    ret = airspy_init_ctrls(dev);
    if (ret < 0)
        goto error_free_dev;

    ret = airspy_video_register(dev);
    if (ret < 0)
        goto error_free_ctrls;

    ret = airspy_get_board_id(dev);
    if (ret < 0)
        dev_info(&dev->intf->dev, "board id read failed, continuing anyway");

    ret = airspy_get_firmware_version(dev);
    if (ret < 0)
        dev_info(&dev->intf->dev, "firmware version read failed");

    dev_info(&dev->intf->dev, "Airspy device registered with v4l2");
    return 0;

error_free_ctrls:
    v4l2_device_unregister(&dev->v4l2_dev);
error_free_dev:
    kfree(dev);
    return ret;
}
